import { useMemo } from "react";
import { CITY, DOMAINS, type Domain } from "./data";
import { rng, wobble, useTick } from "./live";
import { scaled, shareOf, useFilters, type Range, type ZoneFilter } from "./state";

/* every number here that moves is SAMPLE data, generated by code. Counts come from the Excel. */

export const labelsFor = (range: Range): string[] => {
  if (range === "24h") return Array.from({ length: 24 }, (_, i) => `${String(i).padStart(2, "0")}:00`);
  if (range === "7d") return ["Mon", "Tue", "Wed", "Thu", "Fri", "Sat", "Sun"];
  return Array.from({ length: 30 }, (_, i) => `${i + 1}`);
};

interface Def { key: string; base: number; amp: number; seed: number; phase?: number; noise?: number }
/** time series rows with a day-shaped curve; the last point moves on every live refresh */
export function rowsFor(range: Range, tick: number, defs: Def[]): Record<string, number | string>[] {
  const labels = labelsFor(range);
  const n = labels.length;
  return labels.map((t, i) => {
    const row: Record<string, number | string> = { t };
    for (const d of defs) {
      const r = rng(d.seed * 131 + i * 17)();
      const cyc = range === "24h" ? Math.sin(((i - 6) / 24) * Math.PI * 2 + (d.phase ?? 0)) : Math.sin((i / n) * Math.PI * 2 * (range === "7d" ? 1 : 4) + (d.phase ?? 0));
      let v = d.base * (1 + d.amp * cyc + (r - 0.5) * (d.noise ?? 0.06));
      if (i === n - 1) v = wobble(v, d.seed, tick, 0.02);
      row[d.key] = Math.round(v * 100) / 100;
    }
    return row;
  });
}

export interface Health { domain: Domain; score: number }

function build(zone: ZoneFilter, range: Range, tick: number) {
  const w = (b: number, s: number, p = 0.004) => wobble(b, s, tick, p);
  const clamp = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v));
  const S = (kind: Parameters<typeof shareOf>[0]) => shareOf(kind, zone);

  /* meters (AMI) */
  const meters = scaled(CITY.meters, "meters", zone);
  const metersOnlinePct = clamp(w(98.7, 1, 0.003) * 1, 96, 99.9);
  const elec = Math.round(meters * 0.62), water = Math.round(meters * 0.28), gas = meters - elec - water;
  const loadMW = w(118 * S("meters"), 2, 0.02);
  const peakMW = 142 * S("meters");

  /* water */
  const sensors = scaled(CITY.waterSensors, "water", zone);
  const sensorsOnline = clamp(w(99.1, 3, 0.002), 97, 100);
  const pressure = w(4.3, 4, 0.02);
  const flow = w(5200 * S("water"), 5, 0.02);
  const nrw = clamp(w(11.8, 6, 0.03), 8, 16);
  const leaks = Math.max(0, Math.round(w(5 * Math.max(0.3, S("water")), 7, 0.3)));

  /* street lighting */
  const poles = scaled(CITY.poles, "poles", zone);
  const polesFault = Math.round(poles * clamp(w(0.012, 8, 0.2), 0.004, 0.03));
  const polesOn = Math.round((poles - polesFault) * 0.72);
  const polesDim = poles - polesFault - polesOn;
  const saved = clamp(w(38, 9, 0.03), 30, 46);

  /* parking */
  const lots = scaled(CITY.parking, "parking", zone);
  const occPct = clamp(w(64, 10, 0.03) + (zone === "all" ? 0 : (S("parking") - 0.125) * 40), 25, 97);
  const occupied = Math.round(lots * occPct / 100);

  /* transport */
  const stations = Math.max(1, Math.round(CITY.busStations * S("bus")));
  const buses = Math.round(stations * w(1.9, 11, 0.04));
  const wait = clamp(w(6.4, 12, 0.05), 3, 12);
  const onTime = clamp(w(91, 13, 0.01), 80, 98);

  /* signage */
  const screens = scaled(CITY.signage, "signage", zone);
  const screensOnline = clamp(w(97.8, 14, 0.004), 94, 100);

  /* waste */
  const bins = scaled(CITY.bins, "waste", zone);
  const avgFill = clamp(w(54, 15, 0.04), 30, 78);
  const binsFull = Math.round(bins * clamp(w(0.11, 16, 0.2), 0.04, 0.22));
  const trucks = Math.max(1, Math.round(w(18 * S("waste") * 5.5, 17, 0.04)));
  const hist = [0, 1, 2, 3, 4].map((k) => {
    const centre = avgFill / 20;
    return Math.round(bins * Math.exp(-((k + 0.5 - centre) ** 2) / 1.4) * 0.42);
  });

  /* IBMS */
  const points = scaled(CITY.ibmsPoints, "ibms", zone);
  const inAlarm = Math.round(points * clamp(w(0.006, 18, 0.25), 0.002, 0.014));
  const hvacKw = w(2650 * S("ibms") * 4, 19, 0.03);
  const comfort = clamp(w(93, 20, 0.01), 85, 99);

  /* citizens */
  const users = Math.round(CITY.citizenUnits * clamp(w(0.72, 21, 0.02), 0.5, 0.95) * (zone === "all" ? 1 : S("meters") * 1.05));
  const requests = Math.round(w(1840 * (zone === "all" ? 1 : S("meters")), 22, 0.05));
  const resolved = clamp(w(87, 23, 0.02), 70, 98);
  const collection = clamp(w(94.2, 24, 0.008), 85, 99);
  const wallet = Math.round(w(12600 * (zone === "all" ? 1 : S("meters")), 25, 0.05));

  /* security */
  const blocked = Math.round(w(18400, 26, 0.05));
  const eps = Math.round(w(2300, 27, 0.06));
  const openVulns = Math.round(w(37, 28, 0.08));
  const patch = clamp(w(96.4, 29, 0.006), 90, 99.5);
  const mttr = clamp(w(14, 30, 0.08), 6, 30);

  /* platform */
  const cpu = clamp(w(41, 31, 0.06), 20, 85);
  const mem = clamp(w(58, 32, 0.03), 30, 90);
  const storage = clamp(w(63, 33, 0.01), 40, 90);

  const health: Health[] = DOMAINS.map((d, i) => ({ domain: d, score: Math.round(clamp(w(96 - (i % 4) * 1.6 - (d === "Cybersecurity" ? 0.5 : 0), 40 + i, 0.012), 88, 99.5) * 10) / 10 }));
  const overall = Math.round((health.reduce((a, b) => a + b.score, 0) / health.length) * 10) / 10;

  return {
    meters, metersOnlinePct, elec, water, gas, loadMW, peakMW,
    sensors, sensorsOnline, pressure, flow, nrw, leaks,
    poles, polesFault, polesOn, polesDim, saved,
    lots, occPct, occupied,
    stations, buses, wait, onTime,
    screens, screensOnline,
    bins, avgFill, binsFull, trucks, hist,
    points, inAlarm, hvacKw, comfort,
    users, requests, resolved, collection, wallet,
    blocked, eps, openVulns, patch, mttr,
    cpu, mem, storage,
    health, overall,
    series: {
      load: rowsFor(range, tick, [{ key: "Actual", base: 118 * S("meters"), amp: 0.28, seed: 41, phase: 0 }, { key: "Forecast", base: 118 * S("meters"), amp: 0.27, seed: 42, noise: 0.01, phase: 0.1 }]),
      water: rowsFor(range, tick, [{ key: "Flow", base: 5200 * S("water"), amp: 0.22, seed: 43, phase: 0.6 }, { key: "Pressure", base: 4.3, amp: 0.06, seed: 44, noise: 0.02, phase: 0 }]),
      lighting: rowsFor(range, tick, [{ key: "Power", base: 210 * S("poles") * 5, amp: -0.5, seed: 45, phase: 1.5, noise: 0.04 }]),
      parking: rowsFor(range, tick, [{ key: "Occupancy", base: occPct, amp: 0.3, seed: 46, phase: 0.2 }]),
      ridership: rowsFor(range, tick, [{ key: "Riders", base: 3400 * S("bus") * 6, amp: 0.45, seed: 47 }]),
      waste: rowsFor(range, tick, [{ key: "Fill", base: avgFill, amp: 0.25, seed: 48, phase: 0.4 }]),
      hvac: rowsFor(range, tick, [{ key: "HVAC", base: hvacKw, amp: 0.3, seed: 49, phase: 0.8 }]),
      requests: rowsFor(range, tick, [{ key: "Requests", base: requests / 24, amp: 0.4, seed: 50 }, { key: "Resolved", base: (requests / 24) * 0.87, amp: 0.38, seed: 51, phase: 0.2 }]),
      threats: rowsFor(range, tick, [{ key: "Blocked", base: blocked / 24, amp: 0.3, seed: 52, noise: 0.15 }]),
    },
  };
}
export type CityModel = ReturnType<typeof build>;

export function useCity(): CityModel {
  const { zone, range } = useFilters();
  const tick = useTick();
  return useMemo(() => build(zone, range, tick), [zone, range, tick]);
}
